# plot_results.py
# This script reads the JSON results files generated by benchmark_worker.py and creates 
# plots to visualize the performance of the different allgather and broadcast algorithms  
# across message sizes and number of ranks.
#

import json
import os
import sys
import glob
import matplotlib
matplotlib.use("Agg") 
import matplotlib.pyplot as plt
import numpy as np


# Styles
ALGO_STYLES = {
    "ring": {"color": "tab:blue", "marker": "o", "linestyle": "-"},
    "recursive_doubling": {"color": "tab:orange", "marker": "s", "linestyle": "--"},
    "swing": {"color": "tab:green", "marker": "^", "linestyle": "-."},
    "binary_tree": {"color": "tab:red", "marker": "D", "linestyle": "-"},
    "binomial_tree": {"color": "tab:purple", "marker": "v", "linestyle": "--"},
}

# Names for the legends
ALGO_LABELS = {
    "ring": "Ring",
    "recursive_doubling": "Recursive Doubling",
    "swing": "Swing",
    "binary_tree": "Binary Tree",
    "binomial_tree": "Binomial Tree",
}


def sizeToLabel(sizeBytes):
    # Bytes to labels for the x-axis (Bytes to KB/MB)
    if sizeBytes < 1024:
        return f"{sizeBytes}B"
    elif sizeBytes < 1024 * 1024:
        return f"{sizeBytes // 1024}KB"
    else:
        return f"{sizeBytes // (1024 * 1024)}MB"


def loadResults(resultsDir):
    # grab all results_*.json files one per processes group (total number of processes) size
    files = sorted(glob.glob(os.path.join(resultsDir, "results_*.json")))
    allData = []
    for f in files:
        with open(f) as fp:
            data = json.load(fp)
            allData.append(data)
    return allData


def plotVSMessageSize(allData, collective, outputDir, fixedGpSize=None):
    # plot: x = message size, y = time
    # uses the largest available gpSize by default

    # filter data for this collective and gpSize. if fixedGpSize is None, pick the largest one available so we see the most interesting behavior across message sizes.
    if fixedGpSize:
        candidates = [d for d in allData if d["gp_size"] == fixedGpSize and collective in d]
    else:
        candidates = [d for d in allData if collective in d]
        if candidates:
            # pick the biggest gp size so we see the most interesting behavior
            fixedGpSize = max(d["gp_size"] for d in candidates)
            candidates = [d for d in candidates if d["gp_size"] == fixedGpSize]

    if not candidates:
        print(f"No data found for {collective}")
        return

    data = candidates[0]
    algos = data[collective]

    fig, ax = plt.subplots(figsize=(10, 6))

    for algoName, timings in algos.items():
        # timings keys are strings (json), convert back to int for sorting
        sizes = sorted([int(k) for k in timings.keys()])
        timesMs = [timings[str(s)] * 1000 for s in sizes]  # seconds -> ms
        style = ALGO_STYLES.get(algoName, {})
        label = ALGO_LABELS.get(algoName, algoName)
        ax.plot(sizes, timesMs,
                label=label,
                color=style.get("color", None),
                marker=style.get("marker", "o"),
                linestyle=style.get("linestyle", "-"),
                linewidth=2, markersize=6)

    # log scale on both axes makes the trends easier to see
    ax.set_xscale("log", base=2)
    ax.set_yscale("log")
    ax.set_xlabel("Message Size", fontsize=12)
    ax.set_ylabel("Completion Time (ms)", fontsize=12)
    ax.set_title(f"{collective.replace('_', ' ').title()} - Time vs Message Size (ranks={fixedGpSize})", fontsize=14)
    ax.legend(fontsize=10)
    ax.grid(True, which="both", alpha=0.3)

    # set x-ticks to be the actual message sizes we have data for, with labels
    allSizes = set()
    for algoName, timings in algos.items():
        allSizes.update(int(k) for k in timings.keys())
    allSizes = sorted(allSizes)
    ax.set_xticks(allSizes)
    ax.set_xticklabels([sizeToLabel(s) for s in allSizes], rotation=45, ha="right")

    # make layout tight so labels don't get cut off
    plt.tight_layout()
    outpath = os.path.join(outputDir, f"{collective}_vs_msgsize.png")
    plt.savefig(outpath, dpi=150)
    plt.close()
    print(f"Saved: {outpath}")


def plotVSNumRanks(allData, collective, outputDir, fixedMsgSize=None):
    # plot: x = number of ranks, y = time
    # shows how each algorithm scales as we add more processes
    # uses a fixed message size (default 1MB)

    relevant = [d for d in allData if collective in d]
    if not relevant:
        print(f"No data for {collective}")
        return

    if fixedMsgSize is None:
        fixedMsgSize = 1048576 

    # collect timing data: algo -> {gpSize: timeMs}
    algoData = {}
    for d in relevant:
        ws = d["gp_size"]
        for algoName, timings in d[collective].items():
            key = str(fixedMsgSize)
            if key in timings:
                if algoName not in algoData:
                    algoData[algoName] = {}
                algoData[algoName][ws] = timings[key] * 1000  # -> ms

    if not algoData:
        print(f"No data for {collective} at msgSize={fixedMsgSize}")
        return

    fig, ax = plt.subplots(figsize=(10, 6))

    for algoName, wsTimes in algoData.items():
        gpSizes = sorted(wsTimes.keys())
        times = [wsTimes[ws] for ws in gpSizes]
        style = ALGO_STYLES.get(algoName, {})
        label = ALGO_LABELS.get(algoName, algoName)
        ax.plot(gpSizes, times,
                label=label,
                color=style.get("color", None),
                marker=style.get("marker", "o"),
                linestyle=style.get("linestyle", "-"),
                linewidth=2, markersize=8)

    ax.set_xlabel("Number of Ranks", fontsize=12)
    ax.set_ylabel("Completion Time (ms)", fontsize=12)
    ax.set_title(f"{collective.replace('_', ' ').title()} - Time vs Ranks (msg={sizeToLabel(fixedMsgSize)})", fontsize=14)
    ax.legend(fontsize=10)
    ax.grid(True, alpha=0.3)
    ax.set_xticks(sorted(set(ws for algo in algoData.values() for ws in algo.keys())))

    plt.tight_layout()
    outpath = os.path.join(outputDir, f"{collective}_vs_ranks.png")
    plt.savefig(outpath, dpi=150)
    plt.close()
    print(f"Saved: {outpath}")


def main():
    # read all results files and generate plots
    resultsDir = sys.argv[1] if len(sys.argv) > 1 else "/app/results"
    outputDir = sys.argv[2] if len(sys.argv) > 2 else "/app/plots"
    os.makedirs(outputDir, exist_ok=True)

    # load all results files (one per process group size)
    allData = loadResults(resultsDir)
    if not allData:
        print(f"No result files found in {resultsDir}")
        sys.exit(1)

    print(f"Loaded {len(allData)} result file(s)")

    # generate all 4 plots: 2 collectives per 2 plot types
    plotVSMessageSize(allData, "allgather", outputDir)
    plotVSNumRanks(allData, "allgather", outputDir)

    plotVSMessageSize(allData, "broadcast", outputDir)
    plotVSNumRanks(allData, "broadcast", outputDir)

    print(f"\nAll plots saved to {outputDir}/")


if __name__ == "__main__":
    main()
